/** A mark id. */
export type VendorMark = keyof typeof VENDOR_MARKS

/** Mark ids in the settings menu's order. */
export const MARK_IDS: readonly VendorMark[] = [
  'claude',
  'anthropic',
  'openai',
  'gemini',
  'google',
  'kimi',
  'moonshot',
  'qwen',
  'alibaba',
  'zhipu',
  'chatglm',
  'minimax',
  'deepseek',
  'grok',
  'xai',
  'mistral',
  'meta',
  'doubao',
  'hunyuan',
  'wenxin',
  'stepfun',
]

/** Default mark of each preset vendor: the family mark its models are known by. */
const PRESET_MARKS: Readonly<Record<PresetVendor, VendorMark>> = {
  anthropic: 'claude',
  openai: 'openai',
  google: 'gemini',
  moonshotai: 'kimi',
  alibaba: 'qwen',
  zhipuai: 'zhipu',
  minimax: 'minimax',
  deepseek: 'deepseek',
  xai: 'grok',
}

/** Family names in model ids and display names, for models without a preset; the first match wins. */
const FAMILY_MARKS: readonly (readonly [RegExp, VendorMark])[] = [
  [/claude/i, 'claude'],
  [/gpt|codex|(?:^|[^a-z0-9])o[1-9](?:$|[^a-z0-9])/i, 'openai'],
  [/gemini|gemma/i, 'gemini'],
  [/kimi|moonshot/i, 'kimi'],
  [/qwen|qwq/i, 'qwen'],
  [/glm|zhipu/i, 'zhipu'],
  [/minimax|abab/i, 'minimax'],
  [/deepseek/i, 'deepseek'],
  [/grok/i, 'grok'],
  [/mistral|mixtral|codestral|magistral|ministral|devstral|pixtral/i, 'mistral'],
  [/llama/i, 'meta'],
  [/doubao/i, 'doubao'],
  [/hunyuan/i, 'hunyuan'],
  [/ernie|wenxin/i, 'wenxin'],
  [/(?:^|[^a-z0-9])step-?\d/i, 'stepfun'],
]

/**
 * Whether a stored icon choice names a known mark.
 * @param value - the stored choice.
 * @returns true for a mark id.
 */
export function isVendorMark(value: string): value is VendorMark {
  return Object.hasOwn(VENDOR_MARKS, value)
}

/**
 * The mark a model shows unless the user picks one: its preset vendor's mark,
 * else the first family name found in its id or display name.
 * @param modelId - provider-owned model id.
 * @param modelName - catalog display name.
 * @param preset - the model's preset, when it has one.
 * @returns a mark id, or undefined when nothing matches and the tile shows a letter.
 */
export function autoMark(modelId: string, modelName: string, preset: ModelPreset | undefined): VendorMark | undefined {
  if (preset !== undefined) return PRESET_MARKS[preset.vendor]
  const text = `${modelId} ${modelName}`
  return FAMILY_MARKS.find(([pattern]) => pattern.test(text))?.[1]
}
